// And groups predicates with the AND operator between them.
func And(predicates ...predicate.IMBot) predicate.IMBot {
	return predicate.IMBot(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.IMBot) predicate.IMBot {
	return predicate.IMBot(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.IMBot) predicate.IMBot {
	return predicate.IMBot(sql.NotPredicates(p))
}
